// Trusted host UI, not a native JS dialog (Playwright auto-dismisses unhandled dialogs).
function labDialog(message,{input=false,acceptLabel='Continue',title='MyWay confirmation'}={}){
 const d=document.getElementById('labConsent'), field=document.getElementById('labConsentInput'), cancel=document.getElementById('labConsentCancel'), accept=document.getElementById('labConsentAccept');
 if(d.open)return Promise.resolve(input?null:false);
 document.getElementById('labConsentTitle').textContent=title;
 document.getElementById('labConsentText').textContent=message;
 document.getElementById('labConsentInputLabel').hidden=!input;field.value='';accept.textContent=acceptLabel;
 return new Promise(resolve=>{
  let result=input?null:false;
  const close=()=>{cancel.onclick=null;accept.onclick=null;field.onkeydown=null;resolve(result);};
  d.addEventListener('close',close,{once:true});
  cancel.onclick=()=>d.close();
  accept.onclick=()=>{if(input){const val=field.value.trim();if(!/^[A-Za-z][A-Za-z0-9_-]{0,39}$/.test(val)){field.setCustomValidity('Use a letter followed by letters, digits, underscore or hyphen.');field.reportValidity();return;}result=val;}else result=true;d.close();};
  field.setCustomValidity('');field.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();accept.click();}else field.setCustomValidity('');};
  try{d.showModal();if(input)field.focus();else cancel.focus();}catch{d.removeEventListener('close',close);close();}
 });
}
// END LAB_DIALOG
