 for(const r of runs){const fade=Math.min(.8,(r.end-r.start)/3);stops.push(`${purple} ${pct(r.start)}`,`${blue} ${pct(r.start+fade)}`,`${blue} ${pct(r.end-fade)}`,`${purple} ${pct(r.end)}`);}
