async function saveMarked(investigate){if(operation||!selection||!markScope()||selection.artifact_id!==artifact?.id||(['visuals','both'].includes(markScope())&&!hasVisibleVisual()))return;const scope=markScope();operation=true;updateMarkButtons();let saved=null;try{stop();await queue;if(evidenceError)throw Error('Resolve evidence persistence error first');const sel=structuredClone(selection),ids=sel.kind==='time_range'?artifact.narration.filter((n,i)=>sel.end>sel.start?offsets[i]<sel.end&&offsets[i]+durations[i]>sel.start:i===cueAt(sel.start)).map(n=>n.id):[sel.cue_id];if(!ids.length)throw Error('Mark must overlap a cue');const details={selection:sel,composition_root:plan?.root_id??null,composition_revision_ids:plan?.revision_ids??[],composition_time:globalPosition(),feedback_scope:scope,reason:$('reason').value,note:$('note').value,target_cue_ids:ids,scene_state_report:snapshot,scene_state_unverified:true,frame_image:null,frame_capture_limitation:'Exact pixels unavailable; region coordinates and optional generated state only; state is at marked_time, not every point in a selected range',narration:artifact.narration.filter(n=>ids.includes(n.id))};const j=await api('event',{event:{artifact_id:artifact.id,client_event_id:crypto.randomUUID(),type:'feedback',cue_id:sel.cue_id,time:sel.marked_time,details}});saved=j.event;state.events.push(saved);$('note').value='';clearMarks();revisionView();status('Mark saved. '+(investigate?'Preparing Model C investigation.':'You can investigate it later.'));}catch(e){status(e.message);}finally{operation=false;updateMarkButtons();}if(saved&&investigate)await investigateMark(saved.id);}
function makeButton(text,handler){const b=document.createElement('button');b.type='button';b.className='subtle';b.textContent=text;b.onclick=handler;return b;}
async function toggleRevision(id,enabled){if(operation||transitioning)return;operation=true;try{stop();await captureCheckpoint();await queue;const root=state.artifacts[turnNow().variants.bx],r=await api('composition',{root_id:root.id,revision_id:id,enabled});state=r.state;const rev=state.revisions.find(x=>x.id===id);await show({atCue:rev.target_cue_ids[0]});status(enabled?'Revision enabled.':'Original cues restored.');}catch(e){status(e.message);}finally{operation=false;}}
function revisionView(){const turn=turnNow(),panel=$('revisionPanel'),list=$('revisionList');list.replaceChildren();const original=state?.artifacts[turn?.variants?.bx];panel.hidden=!original;if(!original)return;const active=state.artifacts[selectedArtifactId??original.id];$('mark').disabled=false;$('markPoint').disabled=false;updateMarkButtons();$('saveMark').title=active?.parent_id?'Investigate this exact replacement version.':'';const revisions=(state.revisions??[]).filter(r=>r.parent_artifact_id===original.id),chosen=compose(state,original).revision_ids;$('revisionSummary').textContent=chosen.length?chosen.length+' active revision'+(chosen.length===1?'':'s')+' · Original / revised versions':'Revision history';for(const r of revisions){const line=document.createElement('div');line.className='revision-entry';const label=document.createElement('strong');label.textContent=r.target_cue_ids.join(', ')+' · '+(chosen.includes(r.id)?'Active':'Saved');line.append(label);if(r.artifact_id&&r.screen?.allowed!==false)line.append(makeButton(chosen.includes(r.id)?'Restore original':'Use revision',()=>toggleRevision(r.id,!chosen.includes(r.id))));else if(r.decision.route==='RUNTIME')line.append(makeButton('Use suggested speed '+r.decision.runtime_speed+'×',()=>{$('speed').value=r.decision.runtime_speed;$('speed').onchange();}));const details=document.createElement('details'),sum=document.createElement('summary'),body=document.createElement('p');sum.textContent='Investigation';body.textContent=r.decision.reason+' · '+r.decision.uncertainty+' · '+r.decision.revision_direction;details.append(sum,body);line.append(details);list.append(line);}
for(const e of state.events.filter(e=>(e.artifact_id===original.id||state.artifacts[e.artifact_id]?.parent_id===original.id)&&e.type==='feedback'&&Array.isArray(e.details?.target_cue_ids)&&!revisions.some(r=>r.feedback_event_id===e.id)).slice(-8)){const line=document.createElement('div'),label=document.createElement('span');label.textContent=e.details.reason+' · '+(e.details.feedback_scope??'unspecified')+' · '+e.details.target_cue_ids.join(', ')+' ';line.append(label,makeButton('Investigate saved mark',()=>investigateMark(e.id)));list.append(line);}}
async function investigateMark(eventId){if(operation)return;operation=true;let g=null;const locks=['session','sessionSelect','load','newSession','voice','question','enableAuto','pauseAuto','creativeEffort','send',...['ROUTE','A','B_DESIGN','X_IMPLEMENT'].map(r=>'model_'+r)].map(id=>[$(id),$(id).disabled]);try{if(!authorization)throw Error('Mark saved. Authorize a learning session, then select Investigate saved mark.');if(authorization.narration!==preferredVoice()||['ROUTE','A','B_DESIGN','X_IMPLEMENT'].some(r=>authorization.models[r]!==$('model_'+r).value)||(['B_DESIGN','X_IMPLEMENT'].some(r=>authorization.models[r].startsWith('gpt-6'))&&authorization.efforts?.[['B_DESIGN','X_IMPLEMENT'].find(r=>authorization.models[r].startsWith('gpt-6'))]!==$('creativeEffort').value))throw Error('Authorize the displayed configuration first. Mark retained.');if(!await labDialog('Investigate this saved mark with Model C? It will choose whether to call B, X, or neither. Maximum model-call reserve: $'+(authorization.revision_reserve??0).toFixed(3)+' USD, plus separately bounded narration if selected. No automatic paid retries.',{title:'Investigate marked experience',acceptLabel:'Investigate'}))return;locks.forEach(([el])=>el.disabled=true);stop();await captureCheckpoint();await queue;if(evidenceError)throw Error('Evidence persistence failure');g=startGenerationProgress('Model C · Investigating marked moment',true);const j=await api('revise',{feedback_event_id:eventId,request_id:g.id,confirm:true});endGenerationProgress(g,j.progress,'complete');g=null;state=j.state;costs=j.costs??costs;authView(j.authorization,true);selectedArtifactId=null;history();await show({atCue:j.revision.target_cue_ids?.[0]});if(j.revision.artifact_id&&plan?.revision_ids.includes(j.revision.id)){status('Revision added to the timeline. Playing the revised section, then the original.');if(artifact.delivery==='visual'&&!ready&&!visualFailed){const until=performance.now()+9500;while(!ready&&!visualFailed&&performance.now()<until)await new Promise(r=>setTimeout(r,35));}if(!document.hidden)beginPlay();else status('Revision ready. Press Play when you return.');}else status(j.revision.artifact_id?'Revision saved but not enabled. Original remains available; see revision history.':'Model C recommendation saved. See revision history.');}catch(e){if(g)endGenerationProgress(g,e.progress,e.progress?.status??'failed');status(e.message);try{const j=await api('state'+query());state=j.state;costs=j.costs??costs;authView(j.authorization,j.allowReal);$('pendingBanner').hidden=!j.pending;revisionView();}catch{}}finally{locks.forEach(([el,was])=>el.disabled=was);operation=false;}}
$('export').onclick=async()=>{if(operation||transitioning)return;operation=true;$('exportButton').disabled=true;try{stop('research_export');await captureCheckpoint();await queue;status('Preparing offline research replay and ZIP. The Lab remains open; no paid requests.');const r=await fetch('/api/export'+query()+'&artifact='+encodeURIComponent(plan?.root_id??artifact?.id??'')+'&composition=yes&composition_voices='+encodeURIComponent(JSON.stringify(Object.fromEntries(Object.entries(compositionAudio).map(([id,au])=>[id,au.effective_voice??'captions']))))+'&voice='+encodeURIComponent(voice())+'&replay_consent='+(autoReviewConsent===true?'yes':'no'),{headers:{'x-myway-token':token}});if(!r.ok)throw Error('Export failed');const blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=sid+'-r643-research.zip';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);status('Research ZIP downloaded. Check replay manifest for recording status.');}catch(e){status(e.message);}finally{operation=false;$('exportButton').disabled=false;}};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else render();});load().catch(e=>status(e.message));
